 static Node build(int[]a){Node h=null,t=null;for(int v:a){Node n=new Node(v);if(h==null)h=t=n;else{t.next=n;t=n;}}return h;}
 static Node reverse(Node h){Node p=null,c=h;while(c!=null){Node n=c.next;c.next=p;p=c;c=n;}return p;}
