 static Node merge(Node a,Node b){Node d=new Node(0),t=d;while(a!=null&&b!=null){if(a.val<=b.val){t.next=a;a=a.next;}else{t.next=b;b=b.next;}t=t.next;}t.next=(a!=null?a:b);return d.next;}
 static void print(Node h){boolean f=true;while(h!=null){if(!f)System.out.print(" ");System.out.print(h.val);f=false;h=h.next;}}
 public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Node a=build(s,n);int m=s.nextInt();Node b=build(s,m);print(merge(a,b));}
}

