import java.io.*;import java.util.*;
public class Main{
 static class Node{int key,val;Node prev,next;Node(int k,int v){key=k;val=v;}}
 static class LRU{
  int cap;Map<Integer,Node> map=new HashMap<>();Node h=new Node(0,0),t=new Node(0,0);
  LRU(int c){cap=c;h.next=t;t.prev=h;}
  void remove(Node x){x.prev.next=x.next;x.next.prev=x.prev;}
  void addFront(Node x){x.next=h.next;x.prev=h;h.next.prev=x;h.next=x;}
  int get(int k){Node x=map.get(k);if(x==null)return -1;remove(x);addFront(x);return x.val;}
  void put(int k,int v){Node x=map.get(k);if(x!=null){x.val=v;remove(x);addFront(x);return;}x=new Node(k,v);map.put(k,x);addFront(x);if(map.size()>cap){Node z=t.prev;remove(z);map.remove(z.key);}}
 }
 public static void main(String[]a)throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringTokenizer st=new StringTokenizer(br.readLine());int cap=Integer.parseInt(st.nextToken()),q=Integer.parseInt(st.nextToken());LRU c=new LRU(cap);StringBuilder o=new StringBuilder();for(int i=0;i<q;i++){st=new StringTokenizer(br.readLine());String op=st.nextToken();int k=Integer.parseInt(st.nextToken());if(op.equals("put"))c.put(k,Integer.parseInt(st.nextToken()));else{if(o.length()>0)o.append('\n');o.append(c.get(k));}}System.out.print(o);}
}

