 static void print(Node h){boolean f=true;while(h!=null){if(!f)System.out.print(" ");System.out.print(h.val);f=false;h=h.next;}}
 public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Node a=null,ta=null;for(int i=0;i<n;i++){Node z=new Node(s.nextInt());if(a==null)a=ta=z;else{ta.next=z;ta=z;}}int m=s.nextInt();Node b=null,tb=null;for(int i=0;i<m;i++){Node z=new Node(s.nextInt());if(b==null)b=tb=z;else{tb.next=z;tb=z;}}print(add(a,b));}
}
